#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"
mkdir -p results

MASTER_PROMPT='Create a warm 10-second Spanish-language preschool animated scene for the original kids music brand “MusiPum”, ages 3–7, titled “Bumi y Pía descubren el ritmo y la melodía”. Preserve the original character designs from the supplied reference images across ALL shots, without redesigning or changing features, colors, outfits or proportions. Main cast ONLY: Bumi, a cheerful round coral-red bass drum with an ivory expressive face on the drumhead, red gloves holding two wooden drumsticks, silver hardware and red sneakers; Pía, a kind compact violet upright piano/keyboard with expressive eyes, a pink bow on the upper right, white-and-black front keyboard, white gloves and purple shoes. Setting: Villa Compás, a sunny magical music town with pastel-colored houses, musical arches and banners, stone fountain, flowers, soft trees and bright blue sky. Rich high-end stylized 3D animation look: smooth rounded forms, pleasant semi-matte materials, soft warm key light, realistic contact shadows, coherent scale, subtly expressive facial rigs, believable arm/hand animation and keyboard/drum interaction. Keep consistent design and staging with the references; avoid over-stimulation, fast flashes, uncanny faces and hyperactive editing. The scene must match the exact Spanish dialogue and educational goal. Keep the action clear, friendly, and readable for children ages 3–7. Use soft original music and gentle sound design. Display no embedded text or subtitles in the shot.'

NEGATIVE_PROMPT='wrong character design, altered colors, extra characters, adult human, scary face, extra eyes, extra arms, extra fingers, extra drumsticks, deformed keys, floating disconnected parts, changing face geometry, lip-sync out of sync, malformed instruments, text gibberish, autogenerated logo, watermark, stock footage, abrupt flash cuts, strobe lights, overly loud audio, frantic editing, duplicate limbs, morphing'

SCENES=(
  "01|00:00-00:10|Bumi says: ¡MusiPum! ¡La música vive en ti!|Bumi, front-facing wide shot, smiling and waving drumsticks in the sunny Plaza de Villa Compás, with the MusiPum logo reserved for post-production on the upper middle area."
  "02|00:10-00:20|Bumi introduction and three drum hits.|Medium shot. Bumi the coral-red upright bass drum with an ivory front membrane and smiling face, shiny silver drum fittings, two red-gloved arms holding wooden mallets, short legs in red sneakers, hops once and speaks to camera. Three visible mallet contacts exactly match three soft drum sounds."
  "03|00:20-00:30|Pía introduction.|Friendly two-shot. Pía, original small purple upright keyboard/piano with expressive eyes, pink bow on the top right, clean black-and-white keys, and white-gloved hands, waves and smiles next to Bumi, who listens."
  "04|00:30-00:40|Bumi plays drum pattern.|Close-up of Bumi in the same plaza, clear ivory drumhead and two raised mallets. He performs a simple distinct four-beat drum pattern; each mallet touches the drumhead on its actual sound. Soft physical bounce, no extra instruments in frame."
  "05|00:40-00:50|Pía explains rhythm.|Medium two-shot. Pía explains kindly while Bumi listens and tilts his head. Above the characters, simple floating glowing circles show three beats and one rest (three solid colored dots, one empty ring), no textual labels, no clutter."
  "06|00:50-01:00|Invitation to clap.|Medium close-up of Pía at an uncluttered music plaza corner. She raises both white-gloved hands to demonstrate clapping and deliberately waits for children to get ready, making friendly eye contact with camera. Large readable gestures; no flashing lights."
  "07|01:00-01:10|Four beats and pulse.|Full/medium shot of Bumi with four distinct floating colored circles along the lower frame, lighting one at a time while Bumi gently bounces in time and performs four soft claps by tapping his drumsticks. Give the viewer time to imitate."
  "08|01:10-01:20|Pía plays piano notes.|Camera slowly tracks from Pía’s smiling face down to a close readable view of her front piano keys. She plays a simple four-note tune on individual black-and-white keys; corresponding keys depress. Bumi listens in the edge of frame."
  "09|01:20-01:30|Higher and lower notes.|Pía plays two contrasted piano pitches. Floating colored note-shapes move from low-left to high-right as the pitch rises. Slow camera tilt follows the notes; keep original design, easy-to-read composition, no generated text."
  "10|01:30-01:40|Melody explained.|Medium shot Pía smiling and pointing to four colored music note symbols on a soft curved upward melodic ribbon, Bumi watches and hums. Notes appear in sequence matching the melody. No labels or text rendered by the generator."
  "11|01:40-01:50|Sing repeated melody.|Medium shot both characters facing viewer. Pía sings four friendly syllables while corresponding four note symbols rise one by one, with simple believable lip-sync. Bumi nods to the music. Pause for children to echo."
  "12|01:50-02:00|Bumi proposes combined rhythm and melody.|Warm two-shot. Bumi gets an idea, raises a mallet, points to his drum and then to Pía’s keyboard. Pía responds with an excited nod. Subtle camera push-in on friendship and collaborative discovery."
  "13|02:00-02:10|Solo rhythm.|Centered medium shot of Bumi only, with Pía quietly out of focus in the background. Bumi plays a repeatable rhythmic figure with a visible rest; exactly synchronize mallet impacts to drum hits. No piano notes."
  "14|02:10-02:20|Solo melody.|Centered medium shot of Pía only. She plays a four-note recognizable melody with clear moving keys and colored notes ascending across the frame. Bumi stands still listening. No drums or percussion."
  "15|02:20-02:30|Together.|Bright full two-shot, Bumi and Pía playing together. Bumi’s mallets hit the drum on a gentle beat while Pía’s corresponding keys press on successive melody notes. Camera small semicircular track, keep movement smooth, warm celebratory smiles."
  "16|02:30-02:40|Ritmo or melodía question.|Bumi leans toward camera with playful curiosity and asks a question; then plays only the same drum pattern without piano. Soft icon of a drum appears briefly; leave two full seconds silent to invite children’s answer."
  "17|02:40-02:50|Melody question.|Pía gives a happy confirming nod, plays only her four piano pitches while Bumi does not strike his drum. Colored music notes move upward one by one; then Pía looks expectantly to camera, hold two seconds."
  "18|02:50-03:00|Summary and closing.|Bumi and Pía return together to the town square, wave to camera, smile and lightly bow. Small colorful notes float and the composition reserves space for the exact original MusiPum logo to be composited in post. Slow camera pull-back, clean warm end card with no AI-made lettering."
)

for entry in "${SCENES[@]}"; do
  IFS='|' read -r idx ts label desc <<< "$entry"
  scene_dir="results/musipum_scene_${idx}"
  mkdir -p "$scene_dir"
  scene_prompt="$MASTER_PROMPT $desc"
  echo "Generating scene ${idx}: ${label}"
  python3 sample_video.py \
    --video-size 720 1280 \
    --video-length 129 \
    --infer-steps 50 \
    --prompt "$scene_prompt" \
    --neg-prompt "$NEGATIVE_PROMPT" \
    --flow-reverse \
    --use-cpu-offload \
    --save-path "$scene_dir" > "$scene_dir/run.log" 2>&1 || true
  echo "Scene ${idx} generated or attempted: ${scene_dir}"
done

echo "Rendering complete. Final assembly should be done with ffmpeg using the generated scene files."
